// Prompt Engineering — AI Agent Patterns

// Build structured chat messages
fn system(text) => {role: "system", content: text}
fn user(text) => {role: "user", content: text}
fn assistant(text) => {role: "assistant", content: text}

let messages = [
  system("You are a helpful coding assistant."),
  user("What is Arc?"),
  assistant("Arc is a language designed for AI agents."),
  user("Show me a pipeline example.")
]

// Format as chat transcript
for msg in messages {
  print("[{msg.role}]: {msg.content}")
}

// Token estimation (~4 chars per token)
fn estimate_tokens(text) => len(text) / 4

let prompt = messages |> map(m => m.content) |> join(" ")
let tokens = estimate_tokens(prompt)
print("\nEstimated tokens: {tokens}")
print("Estimated cost at $3/1M tokens: ${tokens * 3 / 1000000}")

// Context windowing — keep newest messages within budget
fn window(msgs, max_tokens) {
  let mut result = []
  let mut total = 0
  for msg in reverse(msgs) {
    let t = estimate_tokens(msg.content)
    if total + t > max_tokens { ret result |> reverse }
    result = push(result, msg)
    total = total + t
  }
  result |> reverse
}

let trimmed = window(messages, 30)
print("\nWindowed to 30 tokens:")
for msg in trimmed {
  print("  [{msg.role}]: {msg.content}")
}

// Vector Similarity — RAG Building Blocks

// Dot product of two vectors
fn dot(a, b) {
  let mut sum = 0
  for i in 0..len(a) { sum = sum + a[i] * b[i] }
  sum
}

// Vector magnitude
fn magnitude(v) {
  let mut sum = 0
  for x in v { sum = sum + x * x }
  use math
  math.sqrt(sum)
}

// Cosine similarity (-1 to 1, higher = more similar)
fn cosine(a, b) => dot(a, b) / (magnitude(a) * magnitude(b))

// Test with sample vectors
let query = [1.0, 0.8, 0.2, 0.0]
let doc_a = [0.9, 0.7, 0.3, 0.1]   // similar to query
let doc_b = [0.1, 0.0, 0.8, 0.9]   // different from query
let doc_c = [0.95, 0.85, 0.15, 0.0] // very similar

print("Query vs Doc A: {cosine(query, doc_a)}")
print("Query vs Doc B: {cosine(query, doc_b)}")
print("Query vs Doc C: {cosine(query, doc_c)}")

// Semantic search — rank documents by similarity
let docs = [
  {id: "intro", vec: doc_a},
  {id: "unrelated", vec: doc_b},
  {id: "best_match", vec: doc_c}
]

let ranked = docs
  |> map(d => {id: d.id, score: cosine(query, d.vec)})
  |> sort_by(d => 0 - d.score)

print("\nSearch results:")
for doc in ranked {
  print("  {doc.id}: {doc.score}")
}

// Agent Memory — State Management Pattern

// Simple KV store using a map
let mut memory = {}

fn remember(key, value) {
  memory[key] = value
}

fn recall(key) {
  memory[key]
}

fn forget(key) {
  let mut new_mem = {}
  for k in keys(memory) {
    if k != key { new_mem[k] = memory[k] }
  }
  memory = new_mem
}

// Agent builds up context over a conversation
remember("user:name", "Kai")
remember("user:lang", "Arc")
remember("topic", "AI agents")
remember("turn", 1)

print("Memory after setup:")
for k in keys(memory) {
  print("  {k} = {recall(k)}")
}

// Update state
remember("turn", recall("turn") + 1)
print("\nTurn: {recall("turn")}")

// Forget something
forget("topic")
print("\nAfter forgetting 'topic':")
print("Keys: {keys(memory)}")

